36	  const clean = s => (s || '').replace(ZW, '').replace(/\s+/g, ' ').trim();
37	  const cut = (s, n) => s.length > n ? s.slice(0, n) + '…' : s;
38	  const styleOf = el => getComputedStyle(el);
39	  const cssHidden = el => { const cs = styleOf(el); return cs.display === 'none' || cs.visibility === 'hidden' || cs.visibility === 'collapse'; };
40	  const isHidden = el => el.hidden || el.getAttribute('aria-hidden') === 'true' || (el.tagName === 'INPUT' && el.type === 'hidden') || cssHidden(el);
41	  const pseudo = (el, which) => {
42	    let c; try { c = getComputedStyle(el, which).content; } catch (e) { return ''; }
