119	    return null;
120	  };
121	  const lines = [];
122	  let cur = '', inline = 0;
123	  const flush = () => { if (inline) { cur += ' '; return; } const t = cur.replace(ZW, '').replace(/[ \t ]+/g, ' ').trim(); if (t) lines.push(t); cur = ''; };
