168	        const before = cur;
169	        cur = pseudo(cell, '::before');
170	        for (const c of cell.childNodes) walk(c, collapsed);
171	        cur += pseudo(cell, '::after') + descr(cell);
172	        cells.push(cur.replace(/\s+/g, ' ').trim());
