184	    if ((t === 'ABBR' || t === 'SPAN' || t === 'TD' || t === 'DFN') && el.getAttribute('title')) cur += ' (title: ' + q(el.getAttribute('title')) + ')';
185	    if (t === 'DT') cur += ':';
186	    cur += descr(el);
187	    if (block) flush();
188	  };
189	  const modals = [...document.querySelectorAll('dialog[open],[aria-modal="true"]')].filter(d => !isHidden(d) && (d.tagName !== 'DIALOG' || d.matches(':modal')));
190	  for (const modal of modals) {
191	    lines.push('!! A MODAL DIALOG covers the page; nothing behind it works until it is dealt with:');
192	    walk(modal, false); flush();
193	    lines.push('!! END OF MODAL DIALOG. The page behind it:');
194	  }
195	  const body = document.body || document.documentElement;
196	  if (modals.length) {
197	    // A dialog can be nested inside <main>. Hide it while reading the background so it is not rendered a second
198	    // time with new ids; otherwise the ids reported for its controls no longer point at any element.
