209	# Opens collapsed sections and closes purely informational modal popups (no form controls inside): reading a page
210	# the model chose should not cost it a click per paragraph. Returns the popups it closed.
211	PREPARE_JS = r"""
212	() => {
213	  let opened = 0; const closed = [];
214	  document.querySelectorAll('details:not([open])').forEach(d => { d.open = true; opened++; });
