224	LOGIN_JS = r"""
225	([username, password]) => {
226	  const visible = el => { const cs = getComputedStyle(el); return !el.hidden && cs.display !== 'none' && cs.visibility !== 'hidden' && el.type !== 'hidden'; };
227	  const pass = [...document.querySelectorAll('input[type=password]')].find(visible);
228	  if (!pass) return 'no password field on this page';
229	  const scope = pass.form || document;
230	  const fields = [...scope.querySelectorAll('input')].filter(el => visible(el) && ['text', 'email', '', 'tel'].includes((el.getAttribute('type') || '').toLowerCase()));
231	  const user = fields.filter(el => el.compareDocumentPosition(pass) & Node.DOCUMENT_POSITION_FOLLOWING).pop() || fields[0];
232	  const set = (el, value) => { el.focus(); el.value = value; el.dispatchEvent(new Event('input', { bubbles: true })); el.dispatchEvent(new Event('change', { bubbles: true })); };
233	  if (user) set(user, username);
234	  set(pass, password);
235	  pass.setAttribute('data-login-password', '1');
236	  return 'ok';
237	}
