"""What an agent sees of a browser tab and what it can do there.

`Tab.observe()` renders any web page as accessible text: what a screen reader would announce, with every control
numbered so the model can act on it. Nothing here knows a particular website. It reads labels, descriptions,
tooltips, embedded frames and collapsed sections, drops invisible characters, and leaves every choice of where to go
and what to read to the model.
"""
from __future__ import annotations

import asyncio
import io
import re
import zipfile
from html.parser import HTMLParser
from urllib.parse import urljoin, urlparse

from sanity import same_value

NOT_KEPT = "BUT the field now holds"  # how `fill` reports a field that did not keep what was typed

# Renders one document. Returns {text, next}: `text` with ⟦FRAME:n⟧ markers where embedded documents go, `next` the
# first unused element id. Every control gets data-aid="<id>" so it can be found again.
SNAPSHOT_JS = r"""
(startId) => {
  const ZW = /[​-‏⁠-⁤﻿­͏؜᠎]/g;
  const SKIP = new Set(['SCRIPT','STYLE','NOSCRIPT','TEMPLATE','HEAD','META','LINK','TITLE','OPTION','OPTGROUP',
                        'DATALIST','SOURCE','TRACK','PARAM']);
  const CONTROL = new Set(['INPUT','SELECT','TEXTAREA','BUTTON']);
  let nextId = startId;
  document.querySelectorAll('[data-aid]').forEach(e => e.removeAttribute('data-aid'));
  const described = new Set();
  document.querySelectorAll('[aria-describedby],[aria-labelledby]').forEach(e => {
    ((e.getAttribute('aria-describedby') || '') + ' ' + (e.getAttribute('aria-labelledby') || ''))
      .split(/\s+/).forEach(id => id && described.add(id));
  });
  const clean = s => (s || '').replace(ZW, '').replace(/\s+/g, ' ').trim();
  const cut = (s, n) => s.length > n ? s.slice(0, n) + '…' : s;
  const styleOf = el => getComputedStyle(el);
  const cssHidden = el => { const cs = styleOf(el); return cs.display === 'none' || cs.visibility === 'hidden' || cs.visibility === 'collapse'; };
  const isHidden = el => el.hidden || el.getAttribute('aria-hidden') === 'true' || (el.tagName === 'INPUT' && el.type === 'hidden') || cssHidden(el);
  const pseudo = (el, which) => {
    let c; try { c = getComputedStyle(el, which).content; } catch (e) { return ''; }
    if (!c || c === 'none' || c === 'normal') return '';
    const attr = c.match(/^attr\(([^)]+)\)$/);
    if (attr) return el.getAttribute(attr[1].trim()) || '';
    const quoted = c.match(/^"((?:[^"\\]|\\.)*)"$/) || c.match(/^'((?:[^'\\]|\\.)*)'$/);
    return quoted ? quoted[1].replace(/\\(.)/g, '$1') : '';
  };
  const reversed = el => { const cs = styleOf(el); return cs.direction === 'rtl' && /bidi-override/.test(cs.unicodeBidi); };
  // The text a screen reader would read for a subtree. `force` reads a hidden root (tooltips, descriptions).
  const textOf = (node, force) => {
    if (node.nodeType === 3) return node.nodeValue;
    if (node.nodeType !== 1 || SKIP.has(node.tagName)) return '';
    if (!force && isHidden(node)) return '';
    const label = node.getAttribute('aria-label');
    const role = node.getAttribute('role');
    const tag = node.tagName.toUpperCase();
    if (label && (role === 'img' || tag === 'CANVAS' || tag === 'SVG' || tag === 'IMG')) return ' ' + label + ' ';
    if (tag === 'IMG') return ' ' + (node.getAttribute('alt') || '') + ' ';
    if (tag === 'BR') return '\n';
    if (CONTROL.has(tag) && tag !== 'BUTTON') return '';
    let s = pseudo(node, '::before');
    for (const child of node.childNodes) s += textOf(child, false);
    s += pseudo(node, '::after');
    if (reversed(node)) s = [...s].reverse().join('');
    return s;
  };
  const byIds = ids => clean((ids || '').split(/\s+/).map(id => { const e = id && document.getElementById(id); return e ? textOf(e, true) : ''; }).join(' '));
  const nameOf = el => clean(byIds(el.getAttribute('aria-labelledby')) || el.getAttribute('aria-label') || textOf(el, false) || el.getAttribute('title') || el.getAttribute('value') || '');
  const labelOf = el => {
    const parts = [byIds(el.getAttribute('aria-labelledby')), el.getAttribute('aria-label') || ''];
    if (el.labels) for (const l of el.labels) parts.push(textOf(l, false));
    let s = clean(parts.join(' '));
    if (!s) s = clean(el.getAttribute('placeholder') || el.getAttribute('title') || el.getAttribute('name') || '');
    return s;
  };
  const disabled = el => el.disabled === true || el.getAttribute('aria-disabled') === 'true' || !!el.closest('fieldset[disabled],[inert]');
  const dataHints = el => {
    const out = [];
    for (const a of el.attributes) {
      if (!a.name.startsWith('data-') || a.name === 'data-aid' || out.length >= 3) continue;
      out.push(a.value ? a.name + '=' + cut(clean(a.value), 60) : a.name);
    }
    return out.length ? ' {' + out.join(' ') + '}' : '';
  };
  const hrefOf = el => {
    const raw = el.getAttribute('href') || '';
    try { const u = new URL(raw, location.href); return u.origin === location.origin ? u.pathname + u.search + u.hash : u.href; }
    catch (e) { return raw; }
  };
  const q = s => '"' + cut(clean(s), 160).replace(/"/g, "'") + '"';
  const flags = el => (disabled(el) ? ' (disabled)' : '') + (el.required ? ' (required)' : '') + (el.readOnly ? ' (read-only)' : '');
  const descr = el => { const d = byIds(el.getAttribute('aria-describedby')); return d ? ' (described: ' + q(d) + ')' : ''; };
  const tag = (el, collapsed) => { const id = nextId++; el.setAttribute('data-aid', String(id)); return '[' + id + ']' + (collapsed ? ' (in collapsed menu)' : ''); };
  // One control as text, or null when `el` is not a control.
  const control = (el, collapsed) => {
    const t = el.tagName.toUpperCase(), role = el.getAttribute('role') || '', type = (el.getAttribute('type') || '').toLowerCase();
    if (t === 'A' && el.hasAttribute('href')) return tag(el, collapsed) + ' link ' + q(nameOf(el)) + ' -> ' + cut(hrefOf(el), 200) + dataHints(el) + descr(el);
    if (t === 'BUTTON' || (t === 'INPUT' && ['submit', 'button', 'reset', 'image'].includes(type)) || role === 'button') {
      const nv = el.getAttribute('name') ? ' ' + el.getAttribute('name') + '=' + (el.getAttribute('value') || '') : '';
      return tag(el, collapsed) + ' button ' + q(nameOf(el)) + nv + flags(el) + dataHints(el) + descr(el);
    }
    if (t === 'INPUT' && (type === 'checkbox' || type === 'radio'))
      return tag(el, collapsed) + ' ' + type + ' ' + q(labelOf(el)) + (el.checked ? ' [checked]' : ' [unchecked]') + (el.name ? ' name=' + el.name : '') + (el.value && el.value !== 'on' ? ' value=' + el.value : '') + flags(el);
    if (t === 'INPUT' && type === 'range')
      return tag(el, collapsed) + ' slider ' + q(labelOf(el)) + ' value=' + el.value + ' min=' + (el.min || 0) + ' max=' + (el.max || 100) + flags(el);
    if (t === 'INPUT' && type === 'file') return tag(el, collapsed) + ' file-upload ' + q(labelOf(el)) + flags(el);
    if (t === 'INPUT' || t === 'TEXTAREA') {
      const shown = type === 'password' ? (el.value ? '••••' : '') : el.value;
      return tag(el, collapsed) + ' input' + (type && type !== 'text' ? '(' + type + ')' : '') + ' ' + q(labelOf(el)) + ' value=' + q(shown) + (el.placeholder ? ' placeholder=' + q(el.placeholder) : '') + flags(el) + descr(el);
    }
    if (t === 'SELECT') {
      const options = [...el.options].slice(0, 80).map(o => (o.selected ? '*' : '') + (clean(o.textContent) === o.value ? q(o.value) : q(o.value) + '=' + q(o.textContent)));
      return tag(el, collapsed) + ' select ' + q(labelOf(el)) + flags(el) + ' options(* = selected): ' + options.join('; ') + (el.options.length > 80 ? '; …' : '');
    }
    if (t === 'SUMMARY') return tag(el, collapsed) + ' toggle ' + q(nameOf(el)) + (el.parentElement && el.parentElement.open ? ' [open]' : ' [closed]') + flags(el);
    if (['link', 'tab', 'menuitem', 'option', 'checkbox', 'radio', 'switch', 'treeitem'].includes(role) || el.hasAttribute('onclick') || el.isContentEditable && !el.parentElement.isContentEditable)
      return tag(el, collapsed) + ' ' + (role || 'clickable') + ' ' + q(nameOf(el)) + flags(el) + dataHints(el) + descr(el);
    return null;
  };
  const lines = [];
  let cur = '', inline = 0;
  const flush = () => { if (inline) { cur += ' '; return; } const t = cur.replace(ZW, '').replace(/[ \t ]+/g, ' ').trim(); if (t) lines.push(t); cur = ''; };
  const isBlock = el => { const d = styleOf(el).display; return !(d.startsWith('inline') || d === 'contents' || d === 'table-cell' || d === 'ruby'); };
  const isMenu = el => /^(UL|OL|MENU|DIV)$/.test(el.tagName) && !el.hidden && el.getAttribute('aria-hidden') !== 'true'
    && !!el.querySelector('a[href],button,[role=menuitem]')
    && (!!el.closest('nav,[role=navigation],[role=menubar],[role=menu]') || !!(el.previousElementSibling && el.previousElementSibling.matches('button,summary,[aria-haspopup],[aria-expanded]')));
  const walk = (node, collapsed) => {
    if (node.nodeType === 3) { cur += node.nodeValue.replace(ZW, '').replace(/\s+/g, ' '); return; }
    if (node.nodeType !== 1 || SKIP.has(node.tagName)) return;
    const el = node, t = el.tagName.toUpperCase(), role = el.getAttribute('role') || '';
    if (isHidden(el)) {
      if (role === 'tooltip' || (el.id && described.has(el.id))) { if (!(el.id && described.has(el.id))) cur += ' (tooltip: ' + q(textOf(el, true)) + ') '; return; }
      if (!collapsed && cssHidden(el) && isMenu(el)) { flush(); for (const c of el.childNodes) walk(c, true); flush(); }
      return;
    }
    if (t === 'BR') { flush(); return; }
    if (t === 'HR') { flush(); return; }
    if (t === 'IFRAME' || t === 'FRAME') { flush(); const id = nextId++; el.setAttribute('data-aid', String(id)); lines.push('⟦FRAME:' + id + '⟧' + clean(el.getAttribute('title') || el.getAttribute('aria-label') || '')); return; }
    const label = el.getAttribute('aria-label');
    if (label && (role === 'img' || t === 'CANVAS' || t === 'SVG' || t === 'IMG')) { cur += ' ' + (t === 'CANVAS' ? '[canvas: ' + clean(label) + ']' : clean(label)) + ' ' + descr(el); return; }
    if (t === 'CANVAS') { const s = clean(textOf(el, false)); if (s) cur += ' [canvas: ' + s + '] '; return; }
    if (t === 'IMG') { const s = clean(el.getAttribute('alt')); if (s) cur += ' [image: ' + s + '] '; return; }
    if (t === 'SVG') { const s = clean(textOf(el, false)); if (s) cur += ' [graphic: ' + s + '] '; return; }
    if (t === 'LABEL' && (el.control || el.getAttribute('for'))) {
      // A label is announced with its control; print only controls nested inside it.
      el.querySelectorAll('input,select,textarea,button').forEach(c => { if (!isHidden(c)) { const s = control(c, collapsed); if (s) { flush(); cur += s; flush(); } } });
      return;
    }
    const asControl = control(el, collapsed);
    if (asControl) { if (isBlock(el) || t === 'SELECT') { flush(); cur += asControl; flush(); } else cur += ' ' + asControl + ' '; return; }
    const block = isBlock(el);
    if (block) flush();
    if (/^H[1-6]$/.test(t)) cur += '#'.repeat(+t[1]) + ' ';
    else if (t === 'LI') cur += '- ';
    else if (t === 'SUMMARY') cur += '▸ ';
    else if (t === 'CAPTION') cur += 'Table: ';
    else if (t === 'LEGEND') cur += '· ';
    if (role === 'status' || role === 'alert') cur += '(' + role + ') ';
    if (label && block && !['img'].includes(role)) { cur += '— ' + clean(label) + ' —'; flush(); }
    else if (label && !block && !clean(textOf(el, false)).includes(clean(label))) cur += ' {' + clean(label) + '} ';
    if (block && (el.matches('fieldset[disabled]') || el.hasAttribute('inert'))) { cur += '(LOCKED AREA: the controls below are disabled until this area is unlocked)'; flush(); }
    if (t === 'TR') {
      inline++;
      const cells = [];
      for (const cell of el.children) {
        if (isHidden(cell)) continue;
        const before = cur;
        cur = pseudo(cell, '::before');
        for (const c of cell.childNodes) walk(c, collapsed);
        cur += pseudo(cell, '::after') + descr(cell);
        cells.push(cur.replace(/\s+/g, ' ').trim());
        cur = before;
      }
      inline--;
      cur += cells.join(' | '); flush(); return;
    }
    if (t === 'PRE') { const pre = textOf(el, false).replace(ZW, ''); if (inline) cur += pre.replace(/\s+/g, ' '); else { flush(); pre.split('\n').forEach(l => { if (l.trim()) lines.push(l.replace(/\s+$/, '')); }); } return; }
    cur += pseudo(el, '::before');
    if (reversed(el)) cur += clean(textOf(el, false));
    else for (const c of el.childNodes) walk(c, collapsed);
    cur += pseudo(el, '::after');
    if (t === 'TIME' && el.getAttribute('datetime')) cur += ' (datetime=' + el.getAttribute('datetime') + ')';
    if ((t === 'ABBR' || t === 'SPAN' || t === 'TD' || t === 'DFN') && el.getAttribute('title')) cur += ' (title: ' + q(el.getAttribute('title')) + ')';
    if (t === 'DT') cur += ':';
    cur += descr(el);
    if (block) flush();
  };
  const modals = [...document.querySelectorAll('dialog[open],[aria-modal="true"]')].filter(d => !isHidden(d) && (d.tagName !== 'DIALOG' || d.matches(':modal')));
  for (const modal of modals) {
    lines.push('!! A MODAL DIALOG covers the page; nothing behind it works until it is dealt with:');
    walk(modal, false); flush();
    lines.push('!! END OF MODAL DIALOG. The page behind it:');
  }
  const body = document.body || document.documentElement;
  if (modals.length) {
    // A dialog can be nested inside <main>. Hide it while reading the background so it is not rendered a second
    // time with new ids; otherwise the ids reported for its controls no longer point at any element.
    const hidden = modals.map(m => [m, m.getAttribute('aria-hidden')]);
    hidden.forEach(([m]) => m.setAttribute('aria-hidden', 'true'));
    for (const c of body.childNodes) walk(c, false);
    hidden.forEach(([m, value]) => value === null ? m.removeAttribute('aria-hidden') : m.setAttribute('aria-hidden', value));
  } else walk(body, false);
  flush();
  return { text: lines.join('\n'), next: nextId, title: clean(document.title) };
}
"""

# Opens collapsed sections and closes purely informational modal popups (no form controls inside): reading a page
# the model chose should not cost it a click per paragraph. Returns the popups it closed.
PREPARE_JS = r"""
() => {
  let opened = 0; const closed = [];
  document.querySelectorAll('details:not([open])').forEach(d => { d.open = true; opened++; });
  document.querySelectorAll('dialog[open]').forEach(d => {
    if (!d.matches(':modal') || d.querySelector('input:not([type=hidden]),select,textarea')) return;
    closed.push((d.getAttribute('aria-label') || (d.querySelector('h1,h2,h3') || {}).textContent || 'popup').trim().slice(0, 80));
    try { d.close(); } catch (e) {}
  });
  return { opened, closed };
}
"""

LOGIN_JS = r"""
([username, password]) => {
  const visible = el => { const cs = getComputedStyle(el); return !el.hidden && cs.display !== 'none' && cs.visibility !== 'hidden' && el.type !== 'hidden'; };
  const pass = [...document.querySelectorAll('input[type=password]')].find(visible);
  if (!pass) return 'no password field on this page';
  const scope = pass.form || document;
  const fields = [...scope.querySelectorAll('input')].filter(el => visible(el) && ['text', 'email', '', 'tel'].includes((el.getAttribute('type') || '').toLowerCase()));
  const user = fields.filter(el => el.compareDocumentPosition(pass) & Node.DOCUMENT_POSITION_FOLLOWING).pop() || fields[0];
  const set = (el, value) => { el.focus(); el.value = value; el.dispatchEvent(new Event('input', { bubbles: true })); el.dispatchEvent(new Event('change', { bubbles: true })); };
  if (user) set(user, username);
  set(pass, password);
  pass.setAttribute('data-login-password', '1');
  return 'ok';
}
"""

MAX_OBSERVATION = 14000
UNREADABLE = "(this document could not be read"
PAGE_BREAK = "===== collected page"  # between the pages of a list or document that `collect` followed to its end


class _Text(HTMLParser):
    def __init__(self):
        super().__init__()
        self.parts, self.skip = [], 0

    def handle_starttag(self, tag, attrs):
        if tag in ("script", "style"):
            self.skip += 1
        elif tag in ("p", "div", "tr", "br", "li", "h1", "h2", "h3", "table"):
            self.parts.append("\n")
        elif tag in ("td", "th"):
            self.parts.append(" | ")

    def handle_endtag(self, tag):
        if tag in ("script", "style") and self.skip:
            self.skip -= 1

    def handle_data(self, data):
        if not self.skip:
            self.parts.append(data)


def clean_text(text: str) -> str:
    text = re.sub(r"[​-‏⁠-⁤﻿­͏؜᠎]", "", text)
    return re.sub(r"\n\s*\n+", "\n", re.sub(r"[  ]+", " ", text)).strip()


def without_ids(text: str) -> str:
    """A document for reading only: the element ids of the pages it came from are gone by now."""
    return re.sub(r"\[\d+\] (?=(?:\(in collapsed menu\) )?[a-z-]+(?:\([a-z]+\))? \")", "", text)


def _xml_local(tag: str) -> str:
    return tag.rsplit("}", 1)[-1]


def _xlsx_text(archive: zipfile.ZipFile) -> str:
    """Every sheet of a workbook, one line per row, cells separated by " | " (text cells resolved from the
    shared-strings table, where Excel keeps them apart from the rows)."""
    import xml.etree.ElementTree as ET
    names = set(archive.namelist())
    shared: list[str] = []
    if "xl/sharedStrings.xml" in names:
        for item in ET.fromstring(archive.read("xl/sharedStrings.xml")):
            shared.append("".join(node.text or "" for node in item.iter() if _xml_local(node.tag) == "t"))
    sheets = sorted((n for n in names if n.startswith("xl/worksheets/") and n.endswith(".xml")),
                    key=lambda n: int(re.sub(r"\D", "", n) or 0))
    parts = []
    for sheet in sheets:
        rows = []
        for row in ET.fromstring(archive.read(sheet)).iter():
            if _xml_local(row.tag) != "row":
                continue
            cells = []
            for cell in row:
                if _xml_local(cell.tag) != "c":
                    continue
                value = next((n.text or "" for n in cell.iter() if _xml_local(n.tag) == "v"), None)
                if cell.get("t") == "s" and value is not None and value.isdigit() and int(value) < len(shared):
                    value = shared[int(value)]
                elif cell.get("t") == "inlineStr":
                    value = "".join(n.text or "" for n in cell.iter() if _xml_local(n.tag) == "t")
                cells.append(value or "")
            if any(cells):
                rows.append(" | ".join(cells))
        parts.append(f"=== SHEET {sheet.rsplit('/', 1)[-1]} ===\n" + "\n".join(rows))
    return "\n".join(parts)


def _docx_text(archive: zipfile.ZipFile) -> str:
    """A Word document's paragraphs, one per line; a table row's cells on one line separated by " | "."""
    import xml.etree.ElementTree as ET
    body = ET.fromstring(archive.read("word/document.xml"))

    def text_of(node) -> str:
        return "".join(n.text or "" for n in node.iter() if _xml_local(n.tag) == "t")

    lines = []
    for node in body.iter():
        tag = _xml_local(node.tag)
        if tag == "tr":
            lines.append(" | ".join(text_of(cell) for cell in node if _xml_local(cell.tag) == "tc"))
        elif tag == "p" and not any(_xml_local(parent.tag) == "tc" for parent in _ancestors(body, node)):
            lines.append(text_of(node))
    return "\n".join(line for line in lines if line.strip())


def _ancestors(root, target) -> list:
    parents = {child: parent for parent in root.iter() for child in parent}
    found, node = [], target
    while node in parents:
        node = parents[node]
        found.append(node)
    return found


def _decode(data: bytes) -> str:
    """UTF-8, else Windows-1252 (what German Excel and many older systems write), so umlauts survive."""
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        return data.decode("cp1252", errors="replace")


def document_text(data: bytes, content_type: str, name: str, depth: int = 0) -> str:
    """The text of a fetched file: archives are opened, Word and Excel files are read as text and table rows, markup
    is stripped, PDFs are read when pypdf is installed."""
    kind = (content_type or "").lower()
    lower = name.lower()
    if data[:4] == b"PK\x03\x04" or "zip" in kind or lower.endswith(".zip"):
        try:
            archive = zipfile.ZipFile(io.BytesIO(data))
        except zipfile.BadZipFile:
            return "(unreadable archive)"
        names = set(archive.namelist())
        try:
            if "xl/workbook.xml" in names:
                return clean_text(f"SPREADSHEET {name}\n" + _xlsx_text(archive))
            if "word/document.xml" in names:
                return clean_text(f"DOCUMENT {name}\n" + _docx_text(archive))
        except Exception:  # noqa: BLE001  (a damaged Office file: fall back to reading it as an archive)
            pass
        parts = [f"ARCHIVE {name} with files: " + ", ".join(info.filename for info in archive.infolist())]
        for info in archive.infolist()[:40]:
            if info.is_dir() or depth > 4:
                continue
            parts.append(f"=== FILE {info.filename} ===\n" + document_text(archive.read(info), "", info.filename, depth + 1))
        return "\n".join(parts)
    if data[:5] == b"%PDF-" or "pdf" in kind:
        try:
            from pypdf import PdfReader
            return clean_text("\n".join(page.extract_text() or "" for page in PdfReader(io.BytesIO(data)).pages))
        except Exception as error:  # noqa: BLE001
            return f"(PDF could not be read: {error})"
    text = _decode(data)
    if "html" in kind or "xml" in kind or re.search(r"<(html|body|table|div|p|w:document|worksheet)\b", text[:4000], re.I):
        parser = _Text()
        parser.feed(text)
        text = "".join(parser.parts)
    return clean_text(text)


class Tab:
    """One browser tab on one website, driven by one agent."""

    def __init__(self, page, site: dict):
        self.page = page
        self.site_id = site.get("siteId", "")
        self.base_url = site["url"].rstrip("/")
        self.credentials = site.get("credentials") or {}
        self.frames: list[tuple[int, int, object]] = []  # id range -> frame
        self.document = ""  # what `keep` files: the page as last read, a collected listing or a fetched file
        self.document_source = ""
        self.last_collect: dict | None = None  # how the last `collect` ended: where, control, pages, capped
        self.events: list[str] = []
        self.bad_status = 0
        self.loading: set = set()  # page, frame and data requests that have not come back yet
        self.spares: list = []  # browser contexts of the run's other browsers, for a renewal elsewhere (see renew)
        self.renewals = 0
        self._watch(page)

    def _watch(self, page) -> None:
        page.on("dialog", lambda dialog: asyncio.ensure_future(self._on_dialog(dialog)))
        page.on("response", self._on_response)
        page.on("request", lambda request: self.loading.add(request) if request.resource_type in ("document", "xhr", "fetch") else None)
        page.on("requestfinished", lambda request: self.loading.discard(request))
        page.on("requestfailed", lambda request: self.loading.discard(request))

    async def renew(self) -> str:
        """Swap a broken tab for a fresh one in the same browser: same session and cookies, a clean page. A tab can get
        stuck ("frame was detached", loads that never finish) while the website itself is fine: in sandbox runs the
        investigators' tab kept timing out for minutes while a fresh tab on the same site loaded at once.
        From the second renewal on, the fresh tab opens in another of the run's browsers and logs in again: in sandbox
        runs 41a5de64, c3c4b1e8 and 64397a5e one browser could not load the tender portal for the whole run, fresh
        tabs in it included, while the other browsers kept working."""
        old = self.page
        self.renewals += 1
        moved = self.renewals >= 2 and bool(self.spares)
        context = self.spares[(self.renewals - 2) % len(self.spares)] if moved else old.context
        page = await context.new_page()
        self.page, self.frames, self.loading, self.bad_status = page, [], set(), 0
        self._watch(page)
        try:
            await old.close()
        except Exception:  # noqa: BLE001
            pass
        result = await self.goto(self.base_url + "/")
        if not moved:
            return result
        try:
            result += "; " + await self.login()
        except Exception as error:  # noqa: BLE001
            result += f"; logging in again failed: {str(error)[:120]}"
        return "moved to another browser (this one could not load the website): " + result

    async def screenshot(self) -> str | None:
        """The visible part of the page as a base64 JPEG, for a model that reads images; None when it fails."""
        try:
            import base64
            image = await asyncio.wait_for(self.page.screenshot(type="jpeg", quality=55, full_page=False), 15)
            return base64.b64encode(image).decode("ascii")
        except Exception:  # noqa: BLE001
            return None

    async def _on_dialog(self, dialog):
        self.events.append(f'the browser asked "{dialog.message}" ({dialog.type}); it was accepted')
        try:
            await dialog.accept()
        except Exception:  # noqa: BLE001
            pass

    def _on_response(self, response):
        try:
            if response.request.is_navigation_request() and response.frame == self.page.main_frame:
                self.bad_status = response.status if response.status >= 500 else 0
        except Exception:  # noqa: BLE001
            pass

    async def settle(self):
        """Wait until the page, its frames and the data they fetch have arrived and nothing more is on its way."""
        loop = asyncio.get_running_loop()
        end, quiet = loop.time() + 12, None
        await asyncio.sleep(0.1)  # let a click start its request
        while loop.time() < end:
            if self.loading:
                quiet = None
            elif quiet is None:
                quiet = loop.time()
            elif loop.time() - quiet >= 0.2:
                break
            await asyncio.sleep(0.04)
        else:
            self.loading.clear()  # a request that never ends must not hold up every later step
        for frame in list(self.page.frames):
            try:
                await frame.wait_for_load_state("domcontentloaded", timeout=8000 if frame == self.page.main_frame else 3000)
            except Exception:  # noqa: BLE001
                pass
        for _ in range(3):  # a server error page: retry the same address, as a person would press reload
            if not self.bad_status:
                break
            self.events.append(f"the server answered HTTP {self.bad_status}; reloaded")
            await asyncio.sleep(0.4)
            try:
                await self.page.reload(wait_until="domcontentloaded", timeout=15000)
            except Exception:  # noqa: BLE001
                break

    async def _frame_text(self, frame, start: int, depth: int) -> tuple[str, int]:
        try:
            prepared = await frame.evaluate(PREPARE_JS)
            if prepared["opened"]:
                await self.settle()  # lazy content of the sections just opened
            for name in prepared["closed"]:
                self.events.append(f'closed the popup "{name}"')
            shot = await frame.evaluate(SNAPSHOT_JS, start)
        except Exception as error:  # noqa: BLE001
            return f"{UNREADABLE}: {str(error)[:120]})", start
        self.frames.append((start, shot["next"], frame))
        text, following = shot["text"], shot["next"]
        for marker in re.findall(r"⟦FRAME:(\d+)⟧", text):
            inner = "(embedded document not loaded)"
            if depth < 4:
                try:
                    handle = await frame.query_selector(f'[data-aid="{marker}"]')
                    child = await handle.content_frame() if handle else None
                    if child:
                        try:
                            await child.wait_for_load_state("domcontentloaded", timeout=4000)
                        except Exception:  # noqa: BLE001
                            pass
                        inner, following = await self._frame_text(child, following, depth + 1)
                except Exception as error:  # noqa: BLE001
                    inner = f"(embedded document could not be read: {str(error)[:120]})"
            block = "┌── embedded document: " if inner.strip() else "┌── embedded document (empty): "
            text = text.replace(f"⟦FRAME:{marker}⟧", block, 1).replace(
                block, block, 1)
            # the marker line carries the frame's title; append the frame's content under it
            lines = text.split("\n")
            for index, line in enumerate(lines):
                if line.startswith(block) and not line.endswith("⁣"):
                    lines[index] = line + "⁣"
                    lines.insert(index + 1, "\n".join("│ " + row for row in inner.split("\n")) + "\n└── end of embedded document")
                    break
            text = "\n".join(lines)
        return text.replace("⁣", ""), following

    async def read(self) -> str:
        """The current page as text, with fresh element ids."""
        for _ in range(4):  # a page that navigates while it is read is read again
            await self.settle()
            self.frames = []
            text, _ = await self._frame_text(self.page.main_frame, 1, 0)
            if not text.startswith(UNREADABLE):
                break
        try:
            title = await self.page.title()
        except Exception:  # noqa: BLE001
            title = ""
        self.document = f"url: {self.page.url}\ntitle: {clean_text(title)}\n{clean_text(text)}"
        self.document_source = self.page.url
        return self.document

    async def observe(self) -> str:
        text = await self.read()
        if len(text) > MAX_OBSERVATION:
            text = text[:MAX_OBSERVATION] + f"\n… (page text cut here; {len(text) - MAX_OBSERVATION} more characters. `keep` files the whole page.)"
        return text

    def take_events(self) -> list[str]:
        events, self.events = self.events, []
        return events

    async def _modal_is_open(self) -> bool:
        """Whether a page-level dialog now prevents ordinary controls from being used."""
        script = """() => {
          const visible = el => { const s = getComputedStyle(el); return !el.hidden && el.getAttribute('aria-hidden') !== 'true' && s.display !== 'none' && s.visibility !== 'hidden'; };
          return [...document.querySelectorAll('dialog[open],[aria-modal="true"]')]
            .some(el => visible(el) && (el.tagName !== 'DIALOG' || el.matches(':modal')));
        }"""
        for frame in self.page.frames:
            try:
                if await frame.evaluate(script):
                    return True
            except Exception:  # noqa: BLE001
                continue
        return False

    def _locator(self, aid):
        try:
            number = int(aid)
        except (TypeError, ValueError):
            return None
        for start, end, frame in self.frames:
            if start <= number < end:
                return frame.locator(f'[data-aid="{number}"]')
        return None

    async def _describe(self, locator) -> dict:
        info = await self._describe_raw(locator)
        info["name"] = clean_text(info["name"])[:80]  # without the invisible characters pages hide in names
        return info

    async def _describe_raw(self, locator) -> dict:
        return await locator.evaluate(
            """el => ({tag: el.tagName, type: (el.getAttribute('type') || '').toLowerCase(), href: el.href || '',
                      disabled: el.disabled === true || !!el.closest('fieldset[disabled],[inert]'),
                      name: (el.innerText || el.value || el.getAttribute('aria-label') || '').replace(/\\s+/g, ' ').trim().slice(0, 400)})""")

    async def click(self, aid) -> str:
        locator = self._locator(aid)
        if locator is None or await locator.count() == 0:
            return f"there is no element [{aid}] on the page any more; read the current page"
        info = await self._describe(locator)
        if info["disabled"]:
            return f"[{aid}] is disabled (inside a locked or inert area?); nothing happened"
        before = self.page.url
        try:
            await locator.click(timeout=2500)
        except Exception:  # noqa: BLE001  hidden in a collapsed menu, or covered: activate it directly
            try:
                await locator.evaluate("el => el.click()")
            except Exception as error:  # noqa: BLE001
                return f"could not click [{aid}]: {str(error)[:150]}"
        await self.settle()
        if await self._modal_is_open():
            return "the page now has a modal dialog; read it before acting behind it"
        moved = self.page.url != before
        return f'clicked [{aid}] "{info["name"]}"' + (f"; now at {self.page.url}" if moved else "")

    async def fill(self, aid, text: str, enter: bool = False) -> str:
        locator = self._locator(aid)
        if locator is None or await locator.count() == 0:
            return f"there is no element [{aid}] on the page any more"
        try:
            await locator.fill(str(text), timeout=2500)
        except Exception as error:  # noqa: BLE001
            return f"could not fill [{aid}]: {str(error)[:150]}"
        readback = await self._readback(locator, str(text))  # before Enter can load another page
        if enter:
            await locator.press("Enter")
            await self.settle()
        if await self._modal_is_open():
            return "the page now has a modal dialog; read it before acting behind it"
        return f"filled [{aid}]" + (" and pressed Enter" if enter else "") + readback

    async def _readback(self, locator, typed: str) -> str:
        """What a field holds right after typing, when that is not what was typed: a form can reformat, cut or
        silently refuse a value, and a fill that "worked" proves nothing about what the portal will save."""
        try:
            kind, value = await locator.evaluate(
                """el => [(el.getAttribute('type') || '').toLowerCase(),
                          'value' in el ? String(el.value) : (el.isContentEditable ? el.innerText : null)]""")
        except Exception:  # noqa: BLE001
            return ""
        if kind == "password" or value is None:
            return ""
        shown, wanted = clean_text(value), clean_text(typed)
        if shown == wanted:
            return ""
        if same_value(wanted, shown):
            return f'; the field shows it as "{shown[:80]}"'
        return (f'; {NOT_KEPT} "{shown[:80]}", not what was typed: it changed or refused the value. '
                "Read the field's hint and correct it before you move on")

    async def select(self, aid, value: str) -> str:
        locator = self._locator(aid)
        if locator is None or await locator.count() == 0:
            return f"there is no element [{aid}] on the page any more"
        wanted = str(value)
        for attempt in ({"value": wanted}, {"label": wanted}):
            try:
                await locator.select_option(timeout=2000, **attempt)
                await self.settle()
                if await self._modal_is_open():
                    return "the page now has a modal dialog; read it before acting behind it"
                return f'selected "{wanted}" in [{aid}]'
            except Exception:  # noqa: BLE001
                continue
        options = await locator.evaluate("el => [...(el.options || [])].map(o => o.value + '=' + o.textContent.trim())")
        loose = [o.split("=", 1)[0] for o in options if wanted.lower() in o.lower()]
        if len(loose) == 1:
            await locator.select_option(value=loose[0])
            await self.settle()
            return f'selected "{loose[0]}" in [{aid}]'
        return f'[{aid}] has no option "{wanted}"; options: {"; ".join(options)[:600]}'

    async def set(self, aid, value) -> str:
        locator = self._locator(aid)
        if locator is None or await locator.count() == 0:
            return f"there is no element [{aid}] on the page any more"
        info = await self._describe(locator)
        if info["disabled"]:
            return f"[{aid}] is disabled; nothing happened"
        try:
            if info["type"] in ("checkbox", "radio"):
                wanted = bool(value)
                try:
                    await locator.set_checked(wanted, timeout=1500)
                except Exception:  # noqa: BLE001  covered or restyled: toggle it as its label would
                    if await locator.is_checked() != wanted:
                        await locator.evaluate("el => el.click()")
                if await locator.is_checked() != wanted:
                    return f"[{aid}] did not change; it is still {'unchecked' if wanted else 'checked'}"
            else:  # a slider or another input whose value is set in one go
                await locator.evaluate(
                    """(el, v) => { const proto = Object.getPrototypeOf(el); const d = Object.getOwnPropertyDescriptor(proto, 'value');
                                   d && d.set ? d.set.call(el, String(v)) : el.value = String(v);
                                   el.dispatchEvent(new Event('input', {bubbles: true})); el.dispatchEvent(new Event('change', {bubbles: true})); }""",
                    value)
        except Exception as error:  # noqa: BLE001
            return f"could not set [{aid}]: {str(error)[:150]}"
        await self.settle()
        if await self._modal_is_open():
            return "the page now has a modal dialog; read it before acting behind it"
        return f"set [{aid}] to {value}"

    def _on_site(self, url: str) -> bool:
        return urlparse(url).netloc == urlparse(self.base_url).netloc

    async def goto(self, url: str) -> str:
        target = urljoin(self.page.url if self._on_site(self.page.url) else self.base_url + "/", str(url).strip())
        if not self._on_site(target):
            return f"{target} is not on this website; you only work on {self.base_url}"
        try:
            await self.page.goto(target, wait_until="domcontentloaded", timeout=20000)
        except Exception as error:  # noqa: BLE001
            return f"could not open {target}: {str(error)[:150]}"
        await self.settle()
        return f"opened {self.page.url}"

    async def back(self) -> str:
        try:
            await self.page.go_back(wait_until="domcontentloaded", timeout=15000)
        except Exception as error:  # noqa: BLE001
            return f"could not go back: {str(error)[:120]}"
        await self.settle()
        return f"went back to {self.page.url}"

    async def reload(self) -> str:
        try:
            await self.page.reload(wait_until="domcontentloaded", timeout=15000)
        except Exception as error:  # noqa: BLE001
            return f"could not reload: {str(error)[:120]}"
        await self.settle()
        return "reloaded the page"

    async def login(self) -> str:
        if not self.credentials.get("password"):
            return "there are no credentials for this website"
        outcome = "no password field on this page"
        for frame in self.page.frames:
            try:
                outcome = await frame.evaluate(LOGIN_JS, [self.credentials.get("username", ""), self.credentials["password"]])
            except Exception:  # noqa: BLE001
                continue
            if outcome == "ok":
                await frame.locator("[data-login-password]").first.press("Enter")
                await self.settle()
                return f"entered the credentials and submitted the login form; now at {self.page.url}"
        return outcome

    async def collect(self, aid, max_pages: int = 10) -> str:
        """Follow the paging control the model chose until it is gone, and return every page as one document.
        `last_collect` records how it ended: a list that stopped at the page limit with its control still there is
        not complete, and the answer says so instead of passing for the whole list."""
        self.last_collect = None
        locator = self._locator(aid)
        if locator is None or await locator.count() == 0:
            return f"there is no element [{aid}] on the page any more"
        info = await self._describe(locator)
        if not info["name"]:
            return f"[{aid}] has no label to follow from page to page"
        first, start = self.document, self.page.url
        pages, seen = [first], {first}
        limit = max(1, min(int(max_pages or 10), 30))

        async def next_control():
            for _, _, frame in self.frames:
                candidates = frame.locator("a[href], button, [role=button], [role=link]")
                for index in range(min(await candidates.count(), 200)):
                    candidate = candidates.nth(index)
                    try:
                        label = clean_text(await candidate.evaluate("el => el.innerText || el.value || el.getAttribute('aria-label') || ''"))[:80]
                        if label == info["name"] and (await candidate.evaluate("el => el.tagName")) == info["tag"] \
                                and not await candidate.evaluate(
                                    "el => el.disabled === true || el.getAttribute('aria-disabled') === 'true'"):
                            return candidate
                    except Exception:  # noqa: BLE001
                        continue
            return None

        capped = False
        for turn in range(limit):
            control = await next_control()
            if control is None:
                break
            if turn == limit - 1:  # the page limit ended this, not the list: the control is still there
                capped = True
                break
            try:
                await control.click(timeout=2500)
            except Exception:  # noqa: BLE001
                try:
                    await control.evaluate("el => el.click()")
                except Exception:  # noqa: BLE001
                    break
            await self.read()
            if self.document in seen:
                break
            seen.add(self.document)
            pages.append(self.document)
        self.last_collect = {"where": start, "control": info["name"], "pages": len(pages), "capped": capped}
        more = (f' THE LIST IS NOT COMPLETE: this stopped at the limit of {limit} page(s) and "{info["name"]}" is '
                "still there. Collect again from this page (a higher max_pages reads further) before you treat the "
                "list as complete." if capped else "")
        if len(pages) == 1:
            return (f"max_pages {limit} reads only the page you see." + more if capped
                    else f'"{info["name"]}" led to no further page; the list is the page you see')
        # A button may append rows in place rather than lead to a new page. Compare page bodies without generated
        # element ids or the changing paging control: both change between reads even when every earlier row remains.
        def body(page: str) -> str:
            return "\n".join(line for line in without_ids(page).splitlines()
                             if not re.match(r'(?:button|link) "', line.strip()))

        bodies = [body(page) for page in pages]
        grows = (len(pages) > 1 and info["tag"].upper() != "A"
                 and all(later.startswith(earlier) and len(later) >= len(earlier)
                         for earlier, later in zip(bodies, bodies[1:])))
        if grows:  # a "load more" control: the last page holds every row
            self.document = pages[-1]
            return (f'followed "{info["name"]}" {len(pages) - 1} time(s); '
                    + ("the rows loaded so far are on the page." + more if capped
                       else "the list is now complete on the page"))
        self.document = "\n".join(f"{PAGE_BREAK} {number} =====\n{page}" for number, page in enumerate(pages, 1))
        return (f'followed "{info["name"]}" through {len(pages)} page(s); you are on the last one.{more} COLLECTED '
                f"DOCUMENT (file it with keep if it is relevant):\n{without_ids(self.document)[:MAX_OBSERVATION * 2]}")

    async def fetch(self, aid) -> str:
        """Download what the chosen link points to and read it as a document."""
        locator = self._locator(aid)
        if locator is None or await locator.count() == 0:
            return f"there is no element [{aid}] on the page any more"
        target = await locator.evaluate("el => el.href || el.src || el.getAttribute('data-url') || el.getAttribute('formaction') || ''")
        if not target:
            return f"[{aid}] has no address to download"
        target = urljoin(self.page.url, target)
        if not self._on_site(target):
            return f"{target} is not on this website"
        try:
            response = await self.page.context.request.get(target, timeout=20000)
            data = await response.body()
        except Exception as error:  # noqa: BLE001
            return f"could not download {target}: {str(error)[:150]}"
        name = urlparse(target).path.rsplit("/", 1)[-1] or "download"
        disposition = response.headers.get("content-disposition", "")
        named = re.search(r'filename\*?=(?:UTF-8\'\')?"?([^";]+)', disposition)
        if named:
            name = named.group(1)
        self.document = document_text(data, response.headers.get("content-type", ""), name)
        self.document_source = target
        return (f"downloaded {name} (HTTP {response.status}, {len(data)} bytes). DOCUMENT (file it with keep if it is "
                f"relevant):\n{self.document[:MAX_OBSERVATION * 2]}")

class CaseFile:
    def __init__(self, brief: str, context: dict):
        self.brief = brief
        self.reference = _text(context.get("tender_reference")) or ""
        self.scenario = parse_when(context.get("scenario_date")) or datetime.now(timezone.utc)
        self.company = _text(context.get("company_name")) or ""
        self.vat_id = _text(context.get("vat_id")) or ""
        senders = context.get("authorized_senders") or {}
        self.senders = {topic: (_text(senders.get(topic)) or "").split("@")[0].lower() for topic in TOPICS}
        self.mailbox: str | None = None
        self.positions: dict[str, dict] = {}
        self.clarifications: dict[str, dict] = {}
        self.revisions: dict[str, dict] = {}
        self.requirements: dict[tuple[str, str], dict] = {}
        self.materials: dict[str, dict] = {}
        self.conditions: dict[str, dict[tuple, dict]] = {}
        self.messages: dict[tuple, dict] = {}
        self.evidence: list[dict] = []  # extracted records, retained with the page and agent that supplied them
        self.conflicts: list[str] = []  # where a later document replaced a different value of an earlier one
        self.answers: dict[str, tuple[str, str]] = {}  # question id -> (complete | absent, note)
        self.filed: set[str] = set()
        self.news: dict[str, list[str]] = {}
        self.pending = 0
        self.pending_by_agent: dict[str, int] = {}
        self.version = 0
        self._changed = asyncio.Event()

    # ---- filing evidence -------------------------------------------------------------------------------------

    def pending_for(self, agent: str | None = None) -> int:
        if agent is None:
            return self.pending
        return self.pending_by_agent.get(agent, 0)

    def _bump(self) -> None:
        self.version += 1
        self._changed.set()

    async def wait_change(self, seen: int, timeout: float) -> bool:
        """True once the case file has moved past version `seen`."""
        loop = asyncio.get_running_loop()
        end = loop.time() + timeout
        while self.version == seen:
            self._changed.clear()
            left = end - loop.time()
            if left <= 0:
                return False
            try:
                await asyncio.wait_for(self._changed.wait(), timeout=left)
            except asyncio.TimeoutError:
                return False
        return True

    def take_news(self, agent: str) -> list[str]:
        return self.news.pop(agent, [])

    def file(self, kind: str, text: str, source: str, agent: str) -> str:
        """File a document an agent chose; the extraction runs in the background and reports back as news."""
        if kind not in SHAPES:
            return f'unknown kind "{kind}"; the kinds are: {", ".join(SHAPES)}'
        if len(text.strip()) < 20:
            return "there is no document to file"
        # The pages of a collected list are read side by side: shorter replies, sooner.
        raw_pages = [page for page in re.split(re.escape(PAGE_BREAK) + r" \d+ =====\n", text) if len(page.strip()) >= 20]
        pages = _dedup_collected_pages(raw_pages)
        folder = os.environ.get("AGENT_DOCS_DIR")
        if folder:
            os.makedirs(folder, exist_ok=True)
        fresh = 0
        for page in pages:
            digest = hashlib.sha1((kind + "\n" + page).encode("utf-8", "replace")).hexdigest()
            if digest in self.filed:
                continue
            self.filed.add(digest)
            self.pending += 1
            self.pending_by_agent[agent] = self.pending_by_agent.get(agent, 0) + 1
            fresh += 1
            if folder:  # local tuning only: preserve the exact evidence that was filed, one page per file
                filename = f"{len(self.filed):03d}-{kind}-{digest[:8]}.json"
                with open(os.path.join(folder, filename), "w", encoding="utf-8") as out:
                    json.dump({"kind": kind, "source": source, "agent": agent, "text": page}, out,
                              ensure_ascii=False)
            asyncio.ensure_future(self._extract(kind, page, source, agent, digest))
        if not fresh:
            return f"this document is already filed as {kind}"
        return (f"filed {len(text)} characters ({fresh} page(s)) from {source} as {kind}; the facts in it will be "
                "reported to you")

    async def _extract(self, kind: str, text: str, source: str, agent: str, digest: str = "") -> None:
        try:
            # The extraction schema contains the exact facts needed downstream. Repeating the full rules brief
            # for every page made these independent extraction calls unnecessarily large and slow.
            prompt = (f"The tender reference is {self.reference}; the scenario date is "
                      f"{self.scenario.isoformat()}.\n\nKIND OF RECORD: {kind}\nSHAPE\n{SHAPES[kind]}\n\n"
                      f"EVIDENCE (from {source})\n{text[:60000]}")
            raw = await llm.chat_json([{"role": "system", "content": EXTRACT_SYSTEM}, {"role": "user", "content": prompt}],
                                      # This is schema-constrained transcription, not a navigation decision. The
                                      # sandbox model's thinking mode repeatedly consumed its 150 s timeout here.
                                      think=False, max_tokens=12000, label=f"extract:{kind}",
                                      provider=os.environ.get("EXTRACT_PROVIDER", "qwen"))
            data, validation = validate_extraction(kind, raw)
            if data and sanity.enabled("grounding"):
                data, dropped = sanity.ground(data, text)
                if dropped:
                    note = "not found on the page, so left out: " + ", ".join(dropped[:12])
                    validation = f"{validation}; {note}" if validation else note
                    print(f"[grounding {kind}] {note}"[:1500], flush=True)
            stock_note = _strip_physical_only_stock(text, data) if kind == "material" else ""
            if stock_note:
                validation = f"{validation}; {stock_note}" if validation else stock_note
            summary = self.merge(kind, data) if data else (validation or "the extraction failed; file the document again")
            if data and summary == "nothing usable was found in it":
                data = None
                summary = (f"{stock_note}; no usable records were extracted" if stock_note
                           else "no usable records were extracted; check the evidence and file it again")
            elif validation and data:
                summary = validation + "; " + summary
            if data:
                self.evidence.append({"id": digest, "kind": kind, "source": source, "agent": agent,
                                      "summary": summary, "validation": validation, "extracted": data})
            print(f"[extract {kind}] {source} -> {json.dumps(data, ensure_ascii=False)[:1800]}", flush=True)
        except Exception as error:  # noqa: BLE001
            data = None
            summary = f"the extraction failed ({str(error)[:120]}); file the document again"
        if not data:
            self.filed.discard(digest)  # so that filing it again is accepted rather than refused as a duplicate
        self.news.setdefault(agent, []).append(f"From the {kind} document you filed ({source}): {summary}")
        self.pending = max(0, self.pending - 1)
        left = self.pending_by_agent.get(agent, 0) - 1
        if left > 0:
            self.pending_by_agent[agent] = left
        else:
            self.pending_by_agent.pop(agent, None)
        self._bump()

    def merge(self, kind: str, data: dict) -> str:
        """Merge extracted records; returns a one-line account of what they said."""
        told: list[str] = []
        clashes: list[str] = []

        def put(store: dict, key, row: dict, label: str) -> None:
            for name, earlier, later in _merge(store, key, row):
                clashes.append(f"{label} {name}: {earlier!r} on an earlier document, {later!r} on this one")

        if kind == "positions":
            for row in data.get("positions") or []:
                key = _text(row.get("position"))
                if key:
                    put(self.positions, key, row, f"position {key}")
                    told.append(f"{key}: {row.get('quantity')} {row.get('unit') or ''} -> {row.get('requirement_ref')}")
        elif kind == "clarifications":
            for row in data.get("answers") or []:
                key = _text(row.get("number"))
                if key:
                    self.clarifications[key] = row
                    told.append(f"answer {key} ({row.get('timestamp')})")
        elif kind == "revisions":
            for row in data.get("revisions") or []:
                key = _text(row.get("revision"))
                if key:
                    put(self.revisions, key, row, f"revision {key}")
                    told.append(f"{key}: {row.get('status')} ({row.get('date')})")
        elif kind == "requirements":
            revision = _text(data.get("revision")) or ""
            for row in data.get("requirements") or []:
                key = _text(row.get("requirement_ref"))
                if key:
                    put(self.requirements, (revision, key), row, f"requirement {key} in revision {revision or '?'}")
                    told.append(f"{key} in revision {revision or '?'}: bore {row.get('bore_mm')}, stroke {row.get('stroke_mm')}"
                                f"{' (usable travel)' if row.get('stroke_is_usable_travel') else ''}, {row.get('pressure_bar')} bar, "
                                f"{row.get('mounting')}, certification {row.get('certification')}, group {row.get('catalogue_group')}")
        elif kind == "material":
            for row in data.get("materials") or []:
                key = _text(row.get("material_number"))
                if key:
                    put(self.materials, key, row, f"material {key}")
                    told.append(f"{key}: " + ", ".join(f"{name}={value}" for name, value in row.items()
                                                       if value is not None and name not in ("material_number", "description", "number_format")))
        elif kind == "price_conditions":
            key = _text(data.get("material_number"))
            for row in data.get("conditions") or []:
                if key and row.get("scales"):
                    self.conditions.setdefault(key, {})[(str(row.get("valid_from")), str(row.get("valid_to")))] = row
                    told.append(f"{key}: {row.get('valid_from')}..{row.get('valid_to')} {row.get('currency')} "
                                f"per {row.get('price_unit_pieces')} pcs, {len(row['scales'])} scales")
        elif kind == "mail":
            if _text(data.get("mailbox_address")) and "@" in data["mailbox_address"]:
                self.mailbox = data["mailbox_address"].strip()
            for row in data.get("messages") or []:
                key = (str(row.get("sender")), str(row.get("timestamp")), str(row.get("subject")))
                self.messages[key] = row
                blocks = [topic for topic in ("discount",) + TOPICS if row.get(topic)]
                told.append(f"{row.get('subject')} from {row.get('sender')} at {row.get('timestamp')} about "
                            f"{row.get('tender_reference')}: {row.get('topic')} ({', '.join(blocks) or 'no usable data'})")
        self._bump()
        account = "; ".join(told)[:1500] if told else "nothing usable was found in it"
        if clashes:
            self.conflicts.extend(clashes)
            print(f"[conflict {kind}] " + " | ".join(clashes)[:1200], flush=True)
            account = ("CONFLICT WITH AN EARLIER DOCUMENT (the value filed last is now in use): " + "; ".join(clashes[:6])
                       + ". Two records disagree: check the status, date and reference of both against the brief's "
                         "rules before you rely on either. " + account)
        return account

    # ---- from records to calculator inputs -------------------------------------------------------------------

    def governing_revision(self) -> str | None:
        """The latest current revision; one with requirements on file first, so that a document listed as "current"
        next to the specification (eval variant B: a change notice) cannot replace the specification itself."""
        current = []
        with_requirements = {same for (revision, _ref) in self.requirements for same in [revision] if revision}
        for key, row in self.revisions.items():
            when = parse_when(row.get("date"))
            if row.get("status") == "current" and (when is None or when <= self.scenario):
                filed = any(same_text(key, revision) for revision in with_requirements)
                current.append((filed, when or datetime.min.replace(tzinfo=timezone.utc), key))
        return max(current)[2] if current else None

    def _authorized(self, row: dict, topic: str) -> bool:
        """The brief's test for a record: exact tender reference, authorized sender, not after the scenario date."""
        sender = (_text(row.get("sender")) or "").lower()
        local, _, domain = sender.partition("@")
        if self.senders.get(topic) and local != self.senders[topic]:
            return False
        if self.mailbox and domain and domain != self.mailbox.lower().partition("@")[2]:
            return False
        if (_text(row.get("tender_reference")) or "").upper() != self.reference.upper():
            return False
        when = parse_when(row.get("timestamp"))
        return when is None or when <= self.scenario

    def authorities(self) -> Authorities:
        result = Authorities()
        floor = datetime.min.replace(tzinfo=timezone.utc)
        ordered = sorted(self.messages.values(), key=lambda row: parse_when(row.get("timestamp")) or floor)
        day = self.scenario.date()
        for row in ordered:  # oldest first: a newer record replaces the older one, key by key
            fmt = row.get("number_format")
            discount = row.get("discount") or {}
            if discount.get("approves") and self._authorized(row, "discount_approval"):
                percent = parse_number(discount.get("percent"), fmt)
                if percent is not None:
                    result.discount_percent = percent
                    result.discount_min_order = parse_number(discount.get("min_order_value"), fmt)
            if row.get("condition_rules") and self._authorized(row, "condition_rules"):
                for rule in row["condition_rules"]:
                    if _text(rule.get("group")) and rule.get("discount_applies_to") in ("base_only", "base_and_surcharge", "none"):
                        result.clauses[rule["group"].strip()] = rule["discount_applies_to"]
            if row.get("price_indices") and self._authorized(row, "price_indices"):
                by_code: dict[str, list[dict]] = {}
                for entry in row["price_indices"]:
                    if _text(entry.get("code")):
                        by_code.setdefault(entry["code"].strip(), []).append(entry)
                for code, entries in by_code.items():
                    result.index_rates.pop(code, None)  # the latest message decides this code alone
                    for entry in entries:
                        start, end = parse_when(entry.get("valid_from")), parse_when(entry.get("valid_to"), end_of_day=True)
                        if (start and start.date() > day) or (end and end.date() < day):
                            continue
                        rate = parse_number(entry.get("rate"), fmt)
                        unit = re.search(r"/\s*(mg|g|kg|t)\b", str(entry.get("unit") or "EUR/kg"))
                        if rate is not None:
                            result.index_rates[code] = rate / MASS_TO_GRAMS[unit.group(1) if unit else "kg"]
                            break
            if row.get("tech_release") and self._authorized(row, "tech_release"):
                for entry in row["tech_release"]:
                    reserve = _int(entry.get("reserve_mm_per_end"))
                    if reserve is not None:
                        key = _text(entry.get("reserve_key")) or f"revision {entry.get('revision')}"
                        result.reserves[key] = (_text(entry.get("revision")), reserve)
            if row.get("packaging_tariffs") and self._authorized(row, "packaging_tariffs"):
                for entry in row["packaging_tariffs"]:
                    rate = parse_number(entry.get("eur_per_carton"), fmt)
                    if _text(entry.get("key")) and rate is not None:
                        result.tariffs[entry["key"].strip()] = rate
            if row.get("delivery_release") and self._authorized(row, "delivery_release"):
                for entry in row["delivery_release"]:
                    weeks = _int(entry.get("weeks"))
                    if _text(entry.get("key")) and weeks is not None:
                        result.commitments[entry["key"].strip()] = Commitment(
                            _text(entry.get("material_number")) or "", weeks, _int(entry.get("max_quantity")))
            if row.get("fx_fixing") and self._authorized(row, "fx_fixing"):
                for entry in row["fx_fixing"]:
                    rate = parse_number(entry.get("eur_per_unit"), fmt)
                    if _text(entry.get("key")) and rate is not None:
                        result.fx[entry["key"].strip()] = rate
            if row.get("setup_pools") and self._authorized(row, "setup_pools"):
                for entry in row["setup_pools"]:
                    fee = parse_number(entry.get("fee"), fmt)
                    if _text(entry.get("key")) and fee is not None:
                        result.pools[entry["key"].strip()] = (fee, entry.get("cent_allocation") or "largest_remainder")
            if row.get("project_bonus") and self._authorized(row, "project_bonus"):
                for entry in row["project_bonus"]:
                    bands = []
                    for band in entry.get("bands") or []:
                        lower, percent = parse_number(band.get("from"), fmt), parse_number(band.get("percent"), fmt)
                        if percent is not None:
                            bands.append(BonusBand(lower or Decimal(0), parse_number(band.get("to"), fmt), percent))
                    if _text(entry.get("key")) and bands:
                        result.bonus[entry["key"].strip()] = bands
        return result

    def inputs(self) -> SimpleNamespace:
        governing = self.governing_revision()
        positions = [Position(key, _text(row.get("requirement_ref")) or "", _int(row.get("quantity")) or 0,
                              bool(_resolve_is_set(row.get("unit"), row.get("unit_is_set"))),
                              _text(row.get("description")) or "")
                     for key, row in sorted(self.positions.items())]
        clarifications = []
        for key, row in self.clarifications.items():
            entry = Clarification(key, parse_when(row.get("timestamp")),
                                  withdraws=[str(n).strip() for n in row.get("withdraws") or [] if _text(n)])
            for change in row.get("quantity_changes") or []:
                quantity = _int(change.get("quantity"))
                if _text(change.get("position")) and quantity is not None:
                    # The explicit unit is the source of truth. A model's boolean without a copied unit can
                    # contradict the tender's unit and silently omit an otherwise valid position.
                    entry.quantity_changes.append((change["position"].strip(), quantity,
                                                   _unit_is_set(change.get("unit"))))
            for change in row.get("tech_amendments") or []:
                if _text(change.get("requirement_ref")) and _text(change.get("attribute")) and change.get("value") is not None:
                    entry.amendments.append((_text(change.get("revision")) or "", change["requirement_ref"].strip(),
                                             change["attribute"].strip(), str(change["value"])))
            for assigned in row.get("assignments") or []:
                position = _text(assigned.get("position"))
                if not position:
                    continue
                keys = {kind: _text(assigned.get(kind)) for kind in ASSIGNMENT_KINDS if _text(assigned.get(kind))}
                if keys:
                    entry.assignments.setdefault(position, {}).update(keys)
                fee = parse_number(assigned.get("ordinary_setup_fee"), assigned.get("number_format"))
                if fee is not None:
                    entry.setup_fees[position] = fee
            clarifications.append(entry)
        # A quantity change can also come by mail (eval variant A: the buyer's request changed one position): it
        # counts like a Q&A answer of its date, for exactly this tender reference and not after the scenario date.
        for key, row in self.messages.items():
            changes = [(str(change["position"]).strip(), _int(change.get("quantity")), None)
                       for change in row.get("quantity_changes") or []
                       if isinstance(change, dict) and _text(change.get("position")) and _int(change.get("quantity")) is not None]
            when = parse_when(row.get("timestamp"))
            if (changes and (_text(row.get("tender_reference")) or "").upper() == self.reference.upper()
                    and (when is None or when <= self.scenario)):
                clarifications.append(Clarification(f"mail:{key}", when, quantity_changes=changes))
        requirements = {}
        for (revision, ref), row in self.requirements.items():
            if governing and revision and not same_text(revision, governing):
                continue
            if not governing and revision:
                continue
            requirements[ref] = Requirement(
                ref, _int(row.get("bore_mm")), _int(row.get("stroke_mm")), _int(row.get("pressure_bar")),
                _text(row.get("mounting")), _text(row.get("certification")), _text(row.get("catalogue_group")),
                bool(row.get("stroke_is_usable_travel")), _text(row.get("reserve_key")), _int(row.get("pieces_per_set")))
        materials = []
        for number, row in self.materials.items():
            def grams(name):
                mass = parse_number(row.get(name), row.get("number_format"))
                return None if mass is None else mass * MASS_TO_GRAMS.get(str(row.get(name + "_unit") or "g").lower(), Decimal(1))
            conditions = []
            for record in (self.conditions.get(number) or {}).values():
                fmt = record.get("number_format")
                scales = [(int(parse_number(s.get("min_quantity"), fmt) or 0), parse_number(s.get("price"), fmt))
                          for s in record.get("scales") or [] if parse_number(s.get("price"), fmt) is not None]
                conditions.append(PriceCondition(parse_when(record.get("valid_from")), parse_when(record.get("valid_to"), end_of_day=True),
                                                 (_text(record.get("currency")) or "EUR").upper(), _text(record.get("fx_key")),
                                                 _int(record.get("price_unit_pieces")) or 1, scales))
            materials.append(Material(
                number, row.get("is_active"), _text(row.get("catalogue_group")), _int(row.get("bore_mm")),
                _int(row.get("stroke_mm")), _int(row.get("pressure_bar")), _text(row.get("mounting")),
                _text(row.get("certification")), _int(row.get("carton_size")), grams("allocation_mass"),
                grams("surcharge_mass"), _text(row.get("metal_index_code")), _int(row.get("free_stock")),
                _int(row.get("stock_lead_weeks")), _int(row.get("production_lead_weeks")), conditions))
        return SimpleNamespace(governing=governing, positions=positions, clarifications=clarifications,
                               requirements=requirements, materials=materials, authorities=self.authorities(),
                               no_material={qid.split(":", 1)[1] for qid, (status, _) in self.answers.items()
                                            if qid.startswith("material:") and status == "absent"})

    # ---- what is still unknown -------------------------------------------------------------------------------

    def questions(self) -> list[tuple[str, str]]:
        """The open questions, derived from the brief's rules and the facts on file: id and what to find."""
        facts = self.inputs()
        found: list[tuple[str, str]] = []

        def ask(qid: str, text: str) -> None:
            if qid not in self.answers:
                found.append((qid, text))

        if not facts.positions:
            ask("positions", "The tender's bill of quantities: every position with its number, quantity, unit and "
                             "requirement reference.")
        ask("clarifications", "Every answer in the tender's bidder Q&A, on all of its pages: quantity changes, "
                              "withdrawn answers, technical amendments and the keys an answer assigns to a position. "
                              "Answer this question complete once every page of the Q&A is filed.")
        if not self.mailbox:
            ask("mailbox", "The address of the sales mailbox (shown in the webmail).")
        if not facts.governing:
            ask("revision", "The revision history of the buyer's technical specification, to see which revision is "
                            "marked current.")
        refs = sorted({p.requirement_ref for p in facts.positions if p.requirement_ref})
        answers = active_clarifications(facts.clarifications, self.scenario)
        needs, waiting = resolve_requirements(facts.requirements, facts.governing, answers, facts.authorities)
        if facts.governing:
            lacking = [ref for ref in refs if ref not in needs or needs[ref].missing() or not needs[ref].catalogue_group]
            sets = {p.requirement_ref for p in facts.positions if p.is_set}
            lacking += [ref for ref in sets if ref in needs and not needs[ref].pieces_per_set and ref not in lacking]
            if lacking:
                ask("requirements", f"In specification revision {facts.governing} (the current one), the requirements "
                                    f"{', '.join(lacking)} in full: bore, stroke (nominal or usable travel, with its reserve key), "
                                    "pressure, mounting, certification, catalogue group, pieces per set.")
        for ref, key in waiting.items():
            ask(f"reserve:{ref}", f"The technical release for specification revision {facts.governing} that gives the "
                                  f"per-end reserve ({key}): requirement {ref} states a usable travel.")
        assigned, _ = merged_assignments(answers)
        quantities, _ = final_quantities(facts.positions, answers, needs)
        matched: dict[str, Material] = {}
        for ref in refs:
            need = needs.get(ref)
            if need is None or ref in waiting or need.missing():
                continue
            material = match_material(need, facts.materials)
            if material is None:
                seen = [f"{m.number} ({'active' if m.active else 'not active' if m.active is False else 'status unknown'}, "
                        f"{m.bore_mm}/{m.stroke_mm} mm, {m.pressure_bar} bar, {m.mounting}, {m.certification})"
                        for m in facts.materials if need.catalogue_group and same_text(m.catalogue_group, need.catalogue_group)]
                ask(f"material:{ref}", f"The ERP material for requirement {ref}: active, in catalogue group "
                                       f"{need.catalogue_group}, bore {need.bore_mm} mm, stroke {need.stroke_mm} mm, "
                                       f"{need.pressure_bar} bar, mounting {need.mounting}, certification "
                                       f"{need.certification or 'none'}. File each candidate's technical data and status, "
                                       "also a candidate that seems not to match: the case file does the matching. "
                                       f"On file for this group: {'; '.join(seen) or 'nothing yet'}. Answer absent only "
                                       "when every material of the group is on file and none matches.")
                continue
            matched[ref] = material
            gaps = [label for label, value in (("stock quantity", material.stock), ("lead time from stock", material.stock_lead_weeks),
                                               ("production lead time", material.production_lead_weeks),
                                               ("carton size", material.carton_size), ("allocation mass", material.allocation_mass_g),
                                               ("surcharge mass and metal index code", material.surcharge_mass_g)) if value is None]
            if not any(c.scales and c.valid_on(self.scenario) for c in material.conditions):
                gaps.append("the price condition valid on the scenario date with all its quantity scales")
            if gaps:
                ask(f"data:{material.number}", f"ERP material {material.number} (it matches requirement {ref}) still lacks: "
                                               f"{'; '.join(gaps)}.")
        if facts.authorities.discount_percent is None:
            ask("discount", f"The sales director's most recent discount approval for exactly {self.reference} (inbox and "
                            "archive). File the message; answer absent if no approval exists.")
        labels = {"condition_group": ("the condition rules message", facts.authorities.clauses),
                  "packaging_tariff": ("the packaging tariffs message", facts.authorities.tariffs),
                  "delivery_commitment": ("the delivery release message", facts.authorities.commitments),
                  "setup_pool": ("the setup pools message", facts.authorities.pools),
                  "project_bonus": ("the project bonus message", facts.authorities.bonus)}
        for position in sorted(assigned):
            for kind, key in assigned[position].items():
                label, known = labels[kind]
                if key not in known:
                    extra = ""
                    need = needs.get(next((p.requirement_ref for p in facts.positions if p.position == position), ""))
                    if kind == "delivery_commitment" and need is not None and need.ref in matched:
                        extra = f" (the position's material is {matched[need.ref].number})"
                    ask(f"{kind}:{key}", f"For {self.reference}: {label} that defines {key}, assigned to position {position}{extra}.")
        for material in matched.values():
            if material.index_code and material.index_code not in facts.authorities.index_rates:
                ask(f"index:{material.index_code}", f"For {self.reference}: the latest price index message with the rate of "
                                                    f"{material.index_code} (material {material.number}).")
            for condition in material.conditions:
                if condition.valid_on(self.scenario) and condition.currency != "EUR" and (condition.fx_key or "") not in facts.authorities.fx:
                    ask(f"fx:{condition.fx_key}", f"For {self.reference}: the FX fixing message with the rate of "
                                                  f"{condition.fx_key} ({condition.currency}, material {material.number}).")
        return found

    def answer(self, question: str, status: str, note: str, agent: str | None = None) -> str:
        """An agent closes a question: its evidence is complete, or the thing does not exist."""
        open_ids = {qid for qid, _ in self.questions()}
        if question not in open_ids:
            return f'"{question}" is not an open question'
        if status not in ("complete", "absent"):
            return 'status must be "complete" or "absent"'
        if self.pending_for(agent):
            return "facts from documents you filed are still being extracted; wait for them, then answer"
        if question == "clarifications" and status == "complete" and not self.clarifications:
            return "no Q&A answers have been extracted yet; reopen the Q&A evidence, file it as clarifications, and wait for the extraction result"
        if question.startswith("material:") and status == "absent":
            facts = self.inputs()
            answers = active_clarifications(facts.clarifications, self.scenario)
            needs, _ = resolve_requirements(facts.requirements, facts.governing, answers, facts.authorities)
            need = needs.get(question.split(":", 1)[1])
            group = [m for m in facts.materials if need and need.catalogue_group and same_text(m.catalogue_group, need.catalogue_group)]
            unknown = [m.number for m in group if m.active is None or None in (m.bore_mm, m.stroke_mm, m.pressure_bar, m.mounting)]
            if not group:
                return "no material of that catalogue group is on file yet: search the group and file its materials first"
            if unknown:
                return f"the technical data or status of {', '.join(unknown)} is not on file yet: file it before answering absent"
        if status == "complete" and question.split(":")[0] in ("positions", "revision", "requirements", "reserve", "material", "data"):
            return "this question closes by itself once the facts are on file; file the missing evidence instead"
        self.answers[question] = (status, note)
        self._bump()
        return f"question {question} closed as {status}"

    def status(self) -> str:
        """What is on file, short enough to head every agent turn."""
        facts = self.inputs()
        answers = active_clarifications(facts.clarifications, self.scenario)
        needs, _ = resolve_requirements(facts.requirements, facts.governing, answers, facts.authorities)
        quantities, _ = final_quantities(facts.positions, answers, needs)
        assigned, fees = merged_assignments(answers)
        lines = [f"Tender {self.reference}, scenario date {self.scenario.isoformat()}, mailbox {self.mailbox or 'unknown'}."]
        for p in facts.positions:
            keys = ", ".join(f"{kind} {key}" for kind, key in assigned.get(p.position, {}).items())
            lines.append(f"Position {p.position}: tender quantity {p.quantity}{' sets' if p.is_set else ''}, final "
                         f"{quantities.get(p.position, '?')} pieces, requirement {p.requirement_ref}" + (f"; {keys}" if keys else ""))
        lines.append(f"Q&A answers on file: {', '.join(sorted(self.clarifications)) or 'none'}.")
        lines.append(f"Specification: current revision {facts.governing or 'unknown'}; revisions on file: "
                     + (", ".join(f"{key} {row.get('status')}" for key, row in self.revisions.items()) or "none") + ".")
        for ref, need in sorted(needs.items()):
            lines.append(f"Requirement {ref}: bore {need.bore_mm}, stroke {need.stroke_mm}{' usable travel' if need.usable_travel else ''}, "
                         f"{need.pressure_bar} bar, {need.mounting}, certification {need.certification or 'none'}, group {need.catalogue_group}")
        for m in facts.materials:
            valid = [c for c in m.conditions if c.valid_on(self.scenario)]
            lines.append(f"Material {m.number}: {'active' if m.active else 'NOT active' if m.active is False else 'status ?'}, group "
                         f"{m.catalogue_group}, {m.bore_mm}/{m.stroke_mm} mm, {m.pressure_bar} bar, {m.mounting}, {m.certification}; "
                         f"stock {m.stock}, lead {m.stock_lead_weeks}/{m.production_lead_weeks} wk, carton {m.carton_size}, "
                         f"index {m.index_code}, conditions on file {len(m.conditions)} ({len(valid)} valid on the scenario date"
                         + (f", {valid[0].currency}" + (f" {valid[0].fx_key}" if valid[0].fx_key else "") if valid else "") + ")")
        a = facts.authorities
        lines.append("Authorized mail records: discount "
                     + ("none on file" if a.discount_percent is None else f"{a.discount_percent} %" + (f" if order value >= {a.discount_min_order}" if a.discount_min_order else ""))
                     + "; " + "; ".join(f"{name}: {', '.join(sorted(store)) or '-'}" for name, store in (
                         ("condition groups", a.clauses), ("tariffs", a.tariffs), ("commitments", a.commitments), ("pools", a.pools),
                         ("bonus plans", a.bonus), ("FX", a.fx), ("indices", a.index_rates), ("reserves", a.reserves))))
        return "\n".join(lines)

    def dump(self) -> str:
        return json.dumps({"positions": self.positions, "clarifications": self.clarifications, "revisions": self.revisions,
                           "requirements": {f"{rev}|{ref}": row for (rev, ref), row in self.requirements.items()},
                           "materials": self.materials,
                           "conditions": {key: list(rows.values()) for key, rows in self.conditions.items()},
                           "messages": list(self.messages.values()), "answers": self.answers, "mailbox": self.mailbox,
                           "evidence": self.evidence, "conflicts": self.conflicts},
                          ensure_ascii=False, default=str)


async def read_context(brief: str) -> dict:
    """The tender's identity and the brief's sender rules, read from the brief by the model."""
    return await llm.chat_json([{"role": "system", "content": "You read a task brief and return facts from it as JSON."},
                                {"role": "user", "content": f"{CONTEXT_SHAPE}\n\nTASK BRIEF\n{brief}"}],
                               think=True, max_tokens=1500, label="context")

def _clean(text) -> str:
    return "".join(ch for ch in str(text) if ord(ch) not in _ZERO_WIDTH).strip()


def _as_number(text: str) -> Decimal | None:
    """A typed number in German or English notation ("1.234,56", "1,234.56", "2930,65", "24"), else None."""
    raw = _clean(text).replace(" ", "").replace(" ", "")
    if not re.fullmatch(r"[+-]?[\d.,]+", raw) or not re.search(r"\d", raw):
        return None
    if "," in raw and "." in raw:
        raw = raw.replace(".", "").replace(",", ".") if raw.rfind(",") > raw.rfind(".") else raw.replace(",", "")
    elif "," in raw:
        raw = raw.replace(",", ".") if len(raw.rsplit(",", 1)[1]) != 3 else raw.replace(",", "")
    elif raw.count(".") > 1:
        raw = raw.replace(".", "")
    try:
        return Decimal(raw)
    except InvalidOperation:
        return None


def same_value(typed, shown) -> bool:
    """Whether a field shows what was typed, allowing for another number notation ("12.50" and "12,50")."""
    first, second = _clean(typed), _clean(shown)
    if first.casefold() == second.casefold():
        return True
    number, other = _as_number(first), _as_number(second)
    return number is not None and other is not None and number == other


def _leaves(value, out: list) -> None:
    if isinstance(value, dict):
        for item in value.values():
            _leaves(item, out)
    elif isinstance(value, (list, tuple, set)):
        for item in value:
            _leaves(item, out)
    elif value is not None and value != "":
        out.append(value)


class TypingGuard:
    """Allows the clerk to type only what our data holds. `allow()` adds values learned during the run (a code the
    mailbox colleague read, an address it found)."""

    def __init__(self, *sources):
        self.texts: set[str] = set()
        self.numbers: set[Decimal] = set()
        for source in sources:
            self.allow(source)

    def allow(self, source) -> None:
        values: list = []
        _leaves(source, values)
        for value in values:
            text = _clean(value)
            if not text:
                continue
            self.texts.add(text.casefold())
            number = _as_number(text) if not isinstance(value, (int, float, Decimal)) else Decimal(str(value))
            if number is not None:
                self.numbers.add(number.normalize())

    def __call__(self, action: dict) -> str | None:
        """None when the action may run, else the reason it is blocked."""
        if action.get("do") != "fill":
            return None
        text = _clean(action.get("text", ""))
        if not text:
            return None  # clearing a field is always allowed
        if text.casefold() in self.texts:
            return None
        number = _as_number(text)
        if number is not None and number.normalize() in self.numbers:
            return None
        if any(text.casefold() in known or known in text.casefold() for known in self.texts if len(known) >= 6) \
                and number is None:
            return None  # the same value with a little extra around it, e.g. a code with its label
        return (f'blocked: "{text[:60]}" is not in the bid sheet, the bidder details or anything the mailbox colleague '
                "reported. Type values exactly from that data. If the form asks for something you do not have, ask "
                "the mailbox colleague (ask_mail) or leave the field empty; never make a value up.")


# ---- grounding ------------------------------------------------------------------------------------------------------

# Fields the extraction converts by design (dates to ISO, yes/no, formats, free text): not looked up in the page.
_NOT_GROUNDED = {"timestamp", "date", "valid_from", "valid_to", "number_format", "topic", "status", "status_text",
                 "description", "note", "summary", "subject", "is_active", "unit_is_set", "stroke_is_usable_travel",
                 "unit", "allocation_mass_unit", "surcharge_mass_unit", "price_unit", "currency", "kind"}
_SEPARATOR = re.compile(r"(?<=\d)[.,\s'  ](?=\d)")


def _page_forms(text: str) -> tuple[str, str]:
    plain = re.sub(r"\s+", " ", _clean(text)).lower()
    return plain, _SEPARATOR.sub("", plain)

